/**
 *
 * TooltipManager provides shared delay management for multiple tooltips.
 *
 * [Live Demo](https://www.primereact.org/tooltip/)
 *
 * @module TooltipManager
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UseTooltipManagerExposes, UseTooltipManagerProps, UseTooltipManagerState } from '@primereact/types/headless/tooltip';
/**
 * Defines passthrough(pt) options type in TooltipManager component.
 */
export type TooltipManagerPassThroughType<E> = PassThroughType<TooltipManagerInstance, E>;
/**
 * Defines passthrough(pt) options of TooltipManager component.
 */
export interface TooltipManagerPassThrough {
    /**
     * Used to pass attributes to the manager's DOM element.
     */
    manager?: TooltipManagerPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in TooltipManager component.
 */
export interface TooltipManagerProps extends BaseComponentProps<TooltipManagerInstance, UseTooltipManagerProps, TooltipManagerPassThrough> {
}
/**
 * Defines valid state in TooltipManager component.
 * @extends UseTooltipManagerState
 */
export interface TooltipManagerState extends UseTooltipManagerState {
}
/**
 * Defines the methods and properties exposed by TooltipManager component.
 * @extends UseTooltipManagerExposes
 */
export interface TooltipManagerExposes extends UseTooltipManagerExposes {
}
/**
 * Instance of TooltipManager component.
 */
export type TooltipManagerInstance = ComponentInstance<TooltipManagerProps, TooltipManagerState, TooltipManagerExposes>;
